CREATE VIEW public.platform_party_roles WITH (security_invoker='true') AS
 SELECT acct_customers.party_id,
    acct_customers.tenant_id,
    'customer'::text AS role,
    'acct_customers'::text AS source_table,
    (acct_customers.id)::text AS source_id
   FROM public.acct_customers
  WHERE (acct_customers.party_id IS NOT NULL)
UNION ALL
 SELECT acct_employees.party_id,
    acct_employees.tenant_id,
    'employee'::text AS role,
    'acct_employees'::text AS source_table,
    (acct_employees.id)::text AS source_id
   FROM public.acct_employees
  WHERE (acct_employees.party_id IS NOT NULL)
UNION ALL
 SELECT acct_vendors.party_id,
    acct_vendors.tenant_id,
    'vendor'::text AS role,
    'acct_vendors'::text AS source_table,
    (acct_vendors.id)::text AS source_id
   FROM public.acct_vendors
  WHERE (acct_vendors.party_id IS NOT NULL)
UNION ALL
 SELECT acct_vendors.party_id,
    acct_vendors.tenant_id,
    acct_vendors.vendor_kind AS role,
    'acct_vendors'::text AS source_table,
    (acct_vendors.id)::text AS source_id
   FROM public.acct_vendors
  WHERE ((acct_vendors.party_id IS NOT NULL) AND (acct_vendors.vendor_kind = ANY (ARRAY['supplier'::text, 'contractor'::text])))
UNION ALL
 SELECT cap_stakeholders.party_id,
